<?php
if (!defined('ABSPATH')) { exit; }
final class SPF_Documents {
    public function hooks(){add_action('admin_post_spf_update_document_status',[$this,'update_status']);}
    public static function statuses(){return['draft'=>__('Borrador','sistema-para-farmacias'),'ready'=>__('Listo para validar','sistema-para-farmacias'),'prepared'=>__('Preflight correcto','sistema-para-farmacias'),'pending'=>__('Pendiente de envío (legacy)','sistema-para-farmacias'),'cancelled'=>__('Anulado internamente','sistema-para-farmacias')];}
    public static function fiscal_statuses(){return['not_sent'=>__('No enviado','sistema-para-farmacias'),'submitted'=>__('Enviado / esperando respuesta','sistema-para-farmacias'),'accepted'=>__('Aceptado por autoridad fiscal','sistema-para-farmacias'),'accepted_with_observation'=>__('Aceptado con observación','sistema-para-farmacias'),'rejected'=>__('Rechazado por autoridad fiscal','sistema-para-farmacias'),'transport_error'=>__('Error de transporte','sistema-para-farmacias')];}
    public static function create_for_sale($sale_id,$document_type,$sale_number,$total,$customer_id){global $wpdb;$table=SPF_Database::table('invoices');$sale_id=absint($sale_id);if(!$sale_id){return null;}$existing=$wpdb->get_var($wpdb->prepare("SELECT id FROM $table WHERE sale_id=%d LIMIT 1",$sale_id));if($existing){return(int)$existing;}$documents=SPF_Config::sales_documents();if(!isset($documents[$document_type])){$document_type=SPF_Config::default_sales_document();}$series=SPF_Config::document_series($document_type);$last_row=$wpdb->get_row($wpdb->prepare("SELECT id,correlative FROM $table WHERE serie=%s ORDER BY CAST(correlative AS UNSIGNED) DESC,id DESC LIMIT 1 FOR UPDATE",$series),ARRAY_A);$last=$last_row?(int)$last_row['correlative']:0;$correlative=str_pad((string)($last+1),8,'0',STR_PAD_LEFT);$now=current_time('mysql');$hash=wp_generate_password(32,false,false);$reference=wp_json_encode(['country'=>SPF_Config::country_code(),'document_type'=>$document_type,'series'=>$series,'correlative'=>$correlative,'total'=>round((float)$total,2),'sale_number'=>$sale_number],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$electronic=SPF_Config::electronic_invoicing();$ok=$wpdb->insert($table,['sale_id'=>$sale_id,'document_type'=>$document_type,'serie'=>$series,'correlative'=>$correlative,'sunat_status'=>'draft','internal_status'=>'draft','fiscal_status'=>'not_sent','fiscal_adapter'=>sanitize_key($electronic['adapter']??''),'fiscal_remote_code'=>'','fiscal_remote_message'=>'','pdf_url'=>'','xml_url'=>'','cdr_url'=>'','hash_value'=>$hash,'qr_data'=>$reference,'response_body'=>wp_json_encode(['mode'=>'internal','adapter'=>$electronic['adapter']??'','authority'=>$electronic['authority']??'','customer_id'=>$customer_id,'message'=>__('Comprobante interno creado. Pendiente de validación por el adaptador fiscal del país.','sistema-para-farmacias')],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'created_at'=>$now,'updated_at'=>$now]);return$ok&&$wpdb->insert_id?(int)$wpdb->insert_id:null;}
    public function update_status(){if(!current_user_can(SPF_Roles::INVOICES)&&!current_user_can('manage_options')){wp_die(esc_html__('No tienes permisos para gestionar comprobantes.','sistema-para-farmacias'));}check_admin_referer('spf_update_document_status');$id=absint($_POST['document_id']??0);$status=sanitize_key(wp_unslash($_POST['status']??''));if(!in_array($status,['draft','ready'],true)){$status='draft';}global $wpdb;$wpdb->update(SPF_Database::table('invoices'),['internal_status'=>$status,'sunat_status'=>$status,'updated_at'=>current_time('mysql')],['id'=>$id]);wp_safe_redirect(admin_url('admin.php?page=spf-documents&view_document='.$id));exit;}
}
